package com.eventhub.dto; import com.eventhub.entity.*; import java.time.Instant;
public record RegistrationResponse(Long id,String registrationNumber,Long eventId,String eventTitle,Long userId,String userName,Instant registeredAt,RegistrationStatus status,String ticketId){public static RegistrationResponse from(Registration r){return new RegistrationResponse(r.getId(),r.getRegistrationNumber(),r.getEvent().getId(),r.getEvent().getTitle(),r.getUser().getId(),r.getUser().getFirstName()+" "+r.getUser().getLastName(),r.getRegisteredAt(),r.getStatus(),r.getTicket()==null?null:r.getTicket().getTicketId());}}
